"""Import user-owned JPG/JPEG, PNG and WebP as web copies. Originals stay read-only."""
import argparse
import hashlib
import io
import json
from pathlib import Path
from tempfile import TemporaryDirectory
from PIL import Image, ImageCms, ImageOps, features


DEFAULT_TITLE = '待命名'
HEIC_HINT = '请先在本地将 HEIC/HEIF 转换成 JPG 或 PNG 副本（离线），再导入副本。'

def load_catalog(path):
    if not path.exists():return []
    return json.loads(path.read_text(encoding='utf-8').split('=',1)[1].strip().removesuffix(';'))

def remove_legacy_filenames(records):
    """Clean fields generated by the old importer while retaining edited text."""
    removed = 0
    for record in records:
        if not record.get('real') or record.get('sample') or 'filename' not in record:
            continue
        filename = record.pop('filename')
        if isinstance(filename, str) and filename:
            stem = Path(filename).stem
            if record.get('title') == stem:
                record['title'] = DEFAULT_TITLE
            label = record.get('label')
            if isinstance(label, str) and (label == stem or label.endswith(f' · {stem}')):
                place = record.get('place', '')
                record['label'] = f"{place} · {record.get('title') or DEFAULT_TITLE}"
        removed += 1
    return removed

def metadata(image):
    exif=image.getexif();details=exif.get_ifd(34665) if 34665 in exif else {}
    result={}
    for name,tag in [('camera',272),('lens',42036),('focalLength',37386),('aperture',33437),('exposure',33434),('iso',34855),('capturedAt',36867)]:
        value=details.get(tag,exif.get(tag))
        if value is None:continue
        if isinstance(value,bytes):value=value.decode('utf-8','replace').strip('\0')
        if name in ('camera','lens','capturedAt'):value=str(value)
        else:
            try:value=float(value)
            except (ValueError,TypeError,ZeroDivisionError):continue
        if name=='capturedAt':
            import datetime
            try:datetime.datetime.strptime(value,'%Y:%m:%d %H:%M:%S')
            except ValueError:continue
        result[name]=value
    return result

def import_photo(raw, key, args, stage, srgb, supports_webp):
    with Image.open(io.BytesIO(raw)) as original:
        info = metadata(original)
        oriented = ImageOps.exif_transpose(original)
        image = oriented.convert('RGB')
        if original.info.get('icc_profile'):
            embedded = ImageCms.ImageCmsProfile(io.BytesIO(original.info['icc_profile']))
            image = ImageCms.profileToProfile(image, embedded, srgb, outputMode='RGB')
        if 'A' in oriented.getbands() or 'transparency' in oriented.info:
            background = Image.new('RGB', image.size, 'white')
            background.paste(image, mask=oriented.convert('RGBA').getchannel('A'))
            image = background
        urls, widths, webp = {}, {}, {}
        for variant, limit, quality in [('thumb', 480, 82), ('display', 1600, 88), ('large', 2560, 90)]:
            resized = image.copy()
            resized.thumbnail((limit, limit), Image.Resampling.LANCZOS)
            name = f'{key}-{variant}.jpg'
            resized.save(stage / name, quality=quality, optimize=True, progressive=True, icc_profile=srgb.tobytes())
            urls[variant] = f'assets/uploads/{name}'
            widths[variant] = resized.width
            if variant != 'large' and supports_webp:
                name = f'{key}-{variant}.webp'
                resized.save(stage / name, format='WEBP', quality=80, method=6)
                webp[variant] = f'assets/uploads/{name}'
        year = info.get('capturedAt', '')[:4]
        return {
            'id': key, 'image': key, 'author': args.author,
            'place': args.place, 'region': args.place, 'provinceCode': args.province_code,
            'width': image.width, 'height': image.height, 'metadata': info,
            'urls': urls, 'renditionWidths': widths, 'webp': webp,
            'real': True, 'sample': False, 'title': DEFAULT_TITLE, 'theme': args.theme,
            'tags': [args.tag], 'time': year if year.isdigit() else 'pending',
            'label': f'{args.place} · {DEFAULT_TITLE}',
        }


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--input',required=True,type=Path)
    parser.add_argument('--output-root',type=Path,default=Path(__file__).resolve().parents[1])
    parser.add_argument('--author',choices=['kai','friend'],default='kai')
    parser.add_argument('--place',required=True)
    parser.add_argument('--province-code',required=True,help='六位省级行政区代码')
    parser.add_argument('--theme',default='自然',help='与 site.config.js 中主题值对应')
    parser.add_argument('--tag',default='未分类')
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument('--append', action='store_true', help='保留已有照片并去重（默认）')
    mode.add_argument('--replace', action='store_true', help='仅用本批照片重建作品目录，保留旧图片文件')
    parser.add_argument('--yes', action='store_true', help='确认 --replace 写入')
    parser.add_argument('--dry-run', action='store_true', help='只显示导入计划，不写入文件')
    args = parser.parse_args()
    source, out = args.input.resolve(), args.output_root.resolve()
    assets = out / 'assets/uploads'
    catalog = out / 'content/photos.js'
    if args.replace and not (args.yes or args.dry_run):
        parser.error('--replace 会重建作品目录，请加 --yes 确认，或用 --dry-run 查看计划')
    if not source.is_dir():
        parser.error('--input 必须是存在的照片文件夹')
    if out == source or source in out.parents:
        parser.error('输出目录不能位于原图目录中')
    uploads = assets.resolve()
    if source == uploads or source in uploads.parents or uploads in source.parents:
        parser.error('原图目录不能与输出的 assets/uploads 重叠')
    if len(args.province_code) != 6 or not args.province_code.isdigit():
        parser.error('省级代码必须是六位数字')

    supports_webp = features.check('webp')
    supported = {'.jpg', '.jpeg', '.png'}
    if supports_webp:
        supported.add('.webp')
    files, heic, unsupported_webp = [], 0, 0
    for path in sorted(source.rglob('*')):
        if not path.is_file():
            continue
        suffix = path.suffix.lower()
        if suffix in supported:
            files.append(path)
        elif suffix in ('.heic', '.heif'):
            heic += 1
        elif suffix == '.webp':
            unsupported_webp += 1
    if not files:
        hint = HEIC_HINT if heic else ''
        if unsupported_webp:
            hint += '当前 Pillow 未启用 WebP 支持，请在本地转换为 JPG 或 PNG 副本。'
        parser.error('没有找到可导入的 JPG/JPEG、PNG 或 WebP 照片，未改动作品目录。' + hint)
    if heic:
        print(f'跳过 {heic} 张 HEIC/HEIF。{HEIC_HINT}')
    if unsupported_webp:
        print(f'当前 Pillow 未启用 WebP，跳过 {unsupported_webp} 张。请在本地转换为 JPG 或 PNG 副本。')

    records = [] if args.replace else load_catalog(catalog)
    legacy = remove_legacy_filenames(records)
    ids = {record['id'] for record in records}
    planned = {}
    for file in files:
        key = args.author + '-' + hashlib.sha256(file.read_bytes()).hexdigest()[:16]
        if key not in ids:
            planned[key] = file
            ids.add(key)
    added = len(planned)
    skipped = len(files) - added
    if args.dry_run:
        action = '替换' if args.replace else '追加'
        print(f'预演（{action}）：新增 {added}，跳过重复 {skipped}，导入后共 {len(ids)} 张，清理旧文件名 {legacy} 项。未写入。')
        return

    if added or legacy:
        out.mkdir(parents=True, exist_ok=True)
        srgb = ImageCms.ImageCmsProfile(ImageCms.createProfile('sRGB'))
        # Encode the entire batch before installing files or replacing the catalog.
        with TemporaryDirectory(prefix='.photo-import-', dir=out) as temp:
            stage = Path(temp)
            for index, (key, file) in enumerate(planned.items(), 1):
                try:
                    raw = file.read_bytes()
                    if args.author + '-' + hashlib.sha256(raw).hexdigest()[:16] != key:
                        parser.error('导入过程中有原图变化，请重新运行')
                    records.append(import_photo(raw, key, args, stage, srgb, supports_webp))
                except (OSError, ImageCms.PyCMSError, Image.DecompressionBombError):
                    parser.error(f'无法处理第 {index} 张待导入照片。请检查图像、色彩配置和磁盘空间。作品目录未改动。')
            staged_catalog = stage / 'photos.js'
            staged_catalog.write_text('window.KAI_PHOTOS = ' + json.dumps(records, ensure_ascii=False, indent=2) + ';\n', encoding='utf-8')
            catalog.parent.mkdir(parents=True, exist_ok=True)
            if added:
                assets.mkdir(parents=True, exist_ok=True)
                for file in stage.iterdir():
                    if file != staged_catalog:
                        file.replace(assets / file.name)
            staged_catalog.replace(catalog)
    print(f'Imported {added}; catalog {len(records)}; exact duplicates skipped: {skipped}. Originals unchanged.')
    print('Next: update covers/journeys/about image IDs and essay/fieldNotes/further photo IDs in site.config.js; run tools/check.py.')

if __name__=='__main__':main()
